// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, uint96 v, uint8 decimals) public {
        vm.assume(decimals <= 77);
        uint256 expected = uint256(v) * 10 ** uint256(decimals);
        EchoToken tok = new EchoToken(expected);
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);
        bool ok;
        try c.transfer(from, address(tok), tos, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract EchoToken {
    uint256 public expected;
    constructor(uint256 e) { expected = e; }
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        require(amount == expected, "wrong scaling");
        return true;
    }
}
